"""🚲️ Writes the repair ops of `bicycle-stand`: at 1:500 the tube of the print floor (75.2 mm in the plane of the hoop) is 63 mm across like the bars of the front and the plan (the lateral extent rule allows no wider drawing), an oval section instead of a round one."""
import json, os
K = 0.063 / 0.0752
BEND = {"translation": [0.127279, -0.127279, 0.0], "rotation": [0.0, 0.0, 0.382683, 0.92388], "scale": [1, 1, round(K, 6)]}
ops = [{"op": "solid-set", "scale": "500", "id": i, "set": {"transform": BEND if i.startswith("bend") else {"scale": [1, 1, round(K, 6)]}}} for i in ["leg-left", "bend-left", "top-rail", "bend-right", "leg-right", "crossbar"]]
HIDDEN = {"role": "body", "z": 2.9, "filled": True, "tone": 0.5, "kind": "rect", "x": -0.0315, "w": 0.063, "material": "galv-steel"}
ops.append({"op": "shape-add", "scale": "500", "view": "front", "after": "bend-right", "shape": {"id": "leg-left", "bone": "leg-left", **HIDDEN, "y": 0.0, "h": 0.59585, "region": "hoop-galv"}})
ops.append({"op": "shape-add", "scale": "500", "view": "front", "after": "leg-left", "shape": {"id": "crossbar", "bone": "crossbar", **HIDDEN, "y": 0.3624, "h": 0.0752, "region": "crossbar-galv"}})
ops.append({"op": "set", "path": ["volumes", "500", "decisions", 0], "value": {
    "en": "Body: the 48.3 mm tube is 0.1 mm on paper, below the 75 mm feature, so the tube is 75.2 mm deep in the plane of the hoop at the print floor, thickened inwards from the true outer edge (outer size 0.75 x 0.80 m exact, bend outer radius 204 mm kept, inner 129 mm), and 63 mm across, the oval section that front and plan draw (the lateral extent rule allows 15 mm more than the real 48.3 mm); bends as tori with 12-point sections, the cross rail between the thickened legs.",
    "de": "Körper: das Rohr 48,3 mm ist auf dem Papier 0,1 mm breit, unter der Einzelheit 75 mm, daher ist es in der Bügelebene 75,2 mm tief an der Druckgrenze, vom wahren Außenrand nach innen verdickt (Außenmaß 0,75 x 0,80 m exakt, äußerer Biegeradius 204 mm behalten, innen 129 mm), und quer 63 mm breit, der ovale Querschnitt, den Ansicht und Grundriss zeichnen (die Regel der seitlichen Ausdehnung erlaubt 15 mm mehr als die realen 48,3 mm); Bögen als Tori mit Schnitten aus 12 Punkten, der Querholm zwischen den verdickten Beinen."}})
ops.append({"op": "set", "path": ["representations", "500", "decisions", "silhouette"], "value": {
    "en": "One U band per member at the print floor (75.2 mm = 0.15 mm on paper) with the cross rail between the legs; the 0.75 x 0.80 m outer size and the 204 mm outer bend radius are kept exactly. Front: the near leg and bend end-on as a 63 mm bar; plan: top rail and bends as one 63 mm bar with round ends (the lateral extent may exceed the real 48.3 mm by 15 mm at most, so the 3D tube is an oval of 75.2 mm by 63 mm and the three views are the same body).",
    "de": "Ein U-Band je Stab an der Druckgrenze (75,2 mm = 0,15 mm auf dem Papier) mit dem Querholm zwischen den Beinen; das Außenmaß 0,75 x 0,80 m und der äußere Biegeradius 204 mm bleiben exakt. Ansicht: das nahe Bein und der nahe Bogen von vorn als Balken von 63 mm; Grundriss: Oberholm und Bögen als ein Balken von 63 mm mit runden Enden (die seitliche Ausdehnung darf die realen 48,3 mm um höchstens 15 mm übersteigen, daher ist das 3D-Rohr ein Oval von 75,2 mm mal 63 mm und die drei Ansichten zeigen denselben Körper)."}})
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "ops", "bicycle-stand.json")
open(out, "w").write("[\n" + ",\n".join(json.dumps(o, ensure_ascii=False) for o in ops) + "\n]\n")
